G=load(); print(sorted(G))

def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(p for row in g for p in row).most_common(1)[0][0]
    seen=set(); out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]; seen.add((r,c)); col=g[r][c]
                while st:
                    p=st.pop(); comp.append(p)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dr,p[1]+dc)
                        if 0<=q[0]<H and 0<=q[1]<W and q not in seen and g[q[0]][q[1]]==col:
                            seen.add(q); st.append(q)
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                for rr in range(r0+1,r1):
                    for cc in range(c0+1,c1):
                        out[rr][cc]=2
    return out

